 1	import { readFileSync } from "node:fs";
 2	import { join } from "node:path";
 3	import { PrismaClient } from "@prisma/client";
 4	
 5	export const MIGRATIONS_DIR = join(process.cwd(), "prisma", "migrations");
 6	
 7	export type BackfillStep = {
 8	  id: string;
 9	  description: string;
10	  sqlFile: string;
11	};
12	
13	export const steps: BackfillStep[] = [
14	  {
15	    id: "20240220101500_add_task_status",
16	    description: "Default legacy tasks to status 'open'",
17	    sqlFile: "20240220101500_add_task_status/migration.sql",
18	  },
19	];
20	
21	export function loadSql(step: BackfillStep): string {
22	  return readFileSync(join(MIGRATIONS_DIR, step.sqlFile), "utf8");
23	}
24	
25	export async function applyMigration(sql: string, db: PrismaClient) {
26	  const statements = sql
27	    .split(";")
28	    .map((s) => s.replace(/--[^\n]*/g, "").trim())
29	    .filter((s) => s.length > 0);
30	  let rowsAffected = 0;
31	  for (const statement of statements) {
32	    rowsAffected += await db.$executeRawUnsafe(statement);
33	  }
34	  return { rowsAffected };
35	}
36	
37	export async function run(db = new PrismaClient()) {
38	  for (const step of steps) {
39	    const { rowsAffected } = await applyMigration(loadSql(step), db);
40	    console.log(`[backfill] ${step.id}: ${rowsAffected} row(s)`);
41	  }
42	}
43	
44	if (process.argv[1]?.endsWith("backfill.ts")) {
45	  run().then(() => process.exit(0));
46	}

